def _split_cells(cls, segment: "Segment", cut: int) -> Tuple["Segment", "Segment"]:
    """Split a segment in to two at a given cell position.

    Note that splitting a double-width character, may result in that character turning
    into two spaces.

    Args:
        segment (Segment): A segment to split.
        cut (int): A cell position to cut on.

    Returns:
        A tuple of two segments.
    """
    text, style, control = segment
    _Segment = Segment
    cell_length = segment.cell_length

    if cut <= 0:
        return _Segment("", style, control), _Segment(text, style, control)
    if cut >= cell_length:
        return segment, _Segment("", style, control)

    char_size = get_character_cell_size
    current_pos = 0
    split_index = -1

    for i, char in enumerate(text):
        char_len = char_size(char)
        if current_pos + char_len > cut:
            # Split occurs before this character (i.e., after the previous one)
            split_index = i
            break
        current_pos += char_len

    if split_index != -1:
        before = text[:split_index]
        return (_Segment(before, style, control), _Segment(text[split_index:], style, control))
    else:
        # Fallback if loop finishes without splitting (should be covered by cut >= cell_length check)
        return segment, _Segment("", style, control)

